import{_ as e,o,c as a,ah as n}from"./chunks/framework.B8cRkvxi.js";const i="data:image/png;base64,",s="/projects/AiHand/en/latest/assets/image2.Dz6KLrcq.png",r="/projects/AiHand/en/latest/assets/image21.B3B5at1H.png",c="/projects/AiHand/en/latest/assets/image3.DLCCzk8_.png",l="/projects/AiHand/en/latest/assets/image4.BB1QBZNZ.png",g="/projects/AiHand/en/latest/assets/image5.C2M98lR8.png",d="/projects/AiHand/en/latest/assets/image6.DeJzqiTs.png",m="/projects/AiHand/en/latest/assets/image7.CZ-U5uAa.png",p="/projects/AiHand/en/latest/assets/image8.BsVCZ7QR.png",h="/projects/AiHand/en/latest/assets/image9.BmDl_xkf.png",u="/projects/AiHand/en/latest/assets/image10.CfHa9qff.png",A="/projects/AiHand/en/latest/assets/image11.CWhyVlWN.png",w="/projects/AiHand/en/latest/assets/image12.DVcAb7gt.png",b="/projects/AiHand/en/latest/assets/image13.B0Q2zObV.png",_="/projects/AiHand/en/latest/assets/image14.BQ7cIbdI.png",y="/projects/AiHand/en/latest/assets/image15.DJhn0Ecv.png",f="/projects/AiHand/en/latest/assets/image16.Cs9Gg7rX.png",k="/projects/AiHand/en/latest/assets/image17.BBKCrgku.png",q="/projects/AiHand/en/latest/assets/image18.CST56Czp.png",v="/projects/AiHand/en/latest/assets/image19.C38fyc6i.png",x="/projects/AiHand/en/latest/assets/image20.D5BM1BCT.png",P=JSON.parse('{"title":"3. Online Programming","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Online_Programming.md","filePath":"docs/3.Online_Programming.md"}'),D={name:"docs/3.Online_Programming.md"};function M(O,t,H,z,j,B){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="_3-online-programming" tabindex="-1">3. Online Programming <a class="header-anchor" href="#_3-online-programming" aria-label="Permalink to &quot;3. Online Programming&quot;">​</a></h1><h2 id="_3-1-introduction-to-ide" tabindex="-1">3.1 Introduction to IDE <a class="header-anchor" href="#_3-1-introduction-to-ide" aria-label="Permalink to &quot;3.1 Introduction to IDE&quot;">​</a></h2><p>Micro:bit is a product that does require installing an IDE. Users can start programming directly through the website: <a href="https://makecode.microbit.org/" target="_blank" rel="noreferrer">https://makecode.microbit.org/</a></p><h2 id="_3-2-driver-installation" tabindex="-1">3.2 Driver Installation <a class="header-anchor" href="#_3-2-driver-installation" aria-label="Permalink to &quot;3.2 Driver Installation&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Please ensure the CH341 serial driver is installed on your computer as it may effect the connection and usage of the Microbit controller in the following steps.</p></section><p><strong>If it is already installed, you can skip this section.</strong></p><p>(1) Locate the <strong>ch341ser.exe</strong> serial port driver installer from the <a href="./Appendix.html">Appendix-&gt;Serial Driver Software</a> , and open it.</p><img loading="lazy" height="128" width="95" class="common_img" src="'+i+'"><p>(2) Click the &quot;<strong>Install</strong>&quot; button. Wait a moment for the installation success message to appear.</p><img loading="lazy" height="305" width="532" class="common_img" src="'+s+'"><img loading="lazy" height="147" width="343" class="common_img" src="'+r+'"><h2 id="_3-3-ide-setup-and-toolbar-layout" tabindex="-1">3.3 IDE Setup and Toolbar Layout <a class="header-anchor" href="#_3-3-ide-setup-and-toolbar-layout" aria-label="Permalink to &quot;3.3 IDE Setup and Toolbar Layout&quot;">​</a></h2><p>Open a browser tab and access the programming website by entering:<a href="https://makecode.microbit.org/" target="_blank" rel="noreferrer">https://makecode.microbit.org/</a></p><img loading="lazy" height="931" width="1895" class="common_img" src="'+c+'"><p>To write your own code, click &quot;<strong>New Project</strong>&quot; to enter the project name.</p><img loading="lazy" height="469" width="1268" class="common_img" src="'+l+'"><p>After navigating to the main interface, we can divide the screen into the following two sections as outlined below:</p><img loading="lazy" height="629" width="1268" class="common_img" src="'+g+'"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Area</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">Simulation Area</td><td style="text-align:center;">Used for simulating programming instruction blocks</td></tr><tr><td style="text-align:center;">Tag Selection Area</td><td style="text-align:center;">You can use the built-in or add blocks from the extension packages for programming</td></tr><tr><td style="text-align:center;">Program Editing Area</td><td style="text-align:center;">You can insert, copy, paste, delete, modify in block editing area.</td></tr></tbody></table><h2 id="_3-4-download-program" tabindex="-1">3.4 Download Program <a class="header-anchor" href="#_3-4-download-program" aria-label="Permalink to &quot;3.4 Download Program&quot;">​</a></h2><p>Let&#39;s start by creating a simple program. click on the <strong>&quot;Basic&quot;</strong> tab, then drag the corresponding instruction block to add it in the code editing area, as shown in the figure below:</p><img loading="lazy" height="532" width="761" class="common_img" src="'+d+'"><p>(1) For initial device connection, it is necessary to pair the device first. Upon connection, the browser will remember the connected device. Click &quot;<strong>...</strong>&quot; next to &quot;<strong>Download</strong>&quot; button to select &quot;<strong>Connect Device</strong>&quot; from the options.</p><img loading="lazy" height="241" width="745" class="common_img" src="'+m+'"><p>(2) In the pop-up window, click &quot;<strong>Next</strong>&quot; to continue.</p><img loading="lazy" height="450" width="717" class="common_img" src="'+p+'"><p>(3) Click &quot;<strong>Pair</strong>&quot; and select the device for connection in the pop-up window.</p><img loading="lazy" height="372" width="749" class="common_img" src="'+h+'"><img loading="lazy" height="426" width="444" class="common_img" src="'+u+'"><img loading="lazy" height="405" width="717" class="common_img" src="'+A+'"><p>(4) Once the device is successfully connected, click &quot;<strong>Download</strong>&quot; to download the program. During the download process, the yellow LED near the USB port of micro:bit will blink rapidly and continuously. At this point, please do not disconnect or move the cable to avoid download failure.</p><img loading="lazy" height="70" width="423" class="common_img" src="'+w+'"><p>(5) When the download is complete, the indicator will stop flashing and remain steadily lit. Meanwhile, a download completion message will appear on the programming interface</p><img loading="lazy" height="66" width="419" class="common_img" src="'+b+'"><p>(6) Micro:bit will automatically run the program once it&#39;s powered on.</p><h2 id="_3-5-import-program" tabindex="-1">3.5 Import Program <a class="header-anchor" href="#_3-5-import-program" aria-label="Permalink to &quot;3.5 Import Program&quot;">​</a></h2><p>(1) Connect the micro:bit to your computer using a USB cable. Then open the online MakeCode programming page, click <strong>&quot;Import&quot;</strong> and select <strong>&quot;Import file.&quot;</strong></p><img loading="lazy" height="876" width="1894" class="common_img" src="'+_+'"><p>(2) Then click &quot;<strong>Choose File</strong>,&quot; select the code file to be added, and click <strong>&quot;Continue&quot;</strong> to import the code into the online compiler.</p><img loading="lazy" height="521" width="998" class="common_img" src="'+y+'"><img loading="lazy" height="922" width="1896" class="common_img" src="'+f+'"><h2 id="_3-6-add-extension-package" tabindex="-1">3.6 Add Extension Package <a class="header-anchor" href="#_3-6-add-extension-package" aria-label="Permalink to &quot;3.6 Add Extension Package&quot;">​</a></h2><p>(1) On the main interface, click on <strong>&quot;Extension&quot;</strong> in the left section.</p><img loading="lazy" height="919" width="1894" class="common_img" src="'+k+'"><p>(2) In the pop-up window, enter the extension package address:</p><p>For micro:bit V1.5 version, please add: <a href="https://github.com/Hiwonder/Startbit" target="_blank" rel="noreferrer">https://github.com/Hiwonder/Startbit</a> ;</p><p>For micro:bit V2.0 version, please add: <a href="https://github.com/Hiwonder/StartbitV2" target="_blank" rel="noreferrer">https://github.com/Hiwonder/StartbitV2</a> ;</p><p>Then click on the search icon or press <strong>&quot;Enter&quot;</strong>. You can search for the package. Finally, click on <strong>&quot;Startbit/StartbitV2&quot;</strong> to successfully add it.</p><img loading="lazy" height="679" width="1383" class="common_img" src="'+q+'"><img loading="lazy" height="679" width="1383" class="common_img" src="'+v+'"><img loading="lazy" height="923" width="1045" class="common_img" src="'+x+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Users need to choose the extension package based on the actual version of the micro:bit board they have purchased (the version can be found on the back right corner of the board)</p></section>',52)])])}const S=e(D,[["render",M]]);export{P as __pageData,S as default};
